class Solution { public:
    vector<long long> maximumSegmentSum(vector<int>& nums,vector<int>& removeQueries) {
        int n=nums.size();vector<int> parent(n),sz(n,1);iota(parent.begin(),parent.end(),0);
        vector<long long> sum(n,0),ans(n);vector<char> active(n,0);
        function<int(int)> find=[&](int x){return parent[x]==x?x:parent[x]=find(parent[x]);};
        auto join=[&](int a,int b){a=find(a);b=find(b);if(a==b)return;
            if(sz[a]<sz[b])swap(a,b);parent[b]=a;sz[a]+=sz[b];sum[a]+=sum[b];};
        long long best=0;
        for(int i=n-1;i>=0;--i){
            ans[i]=best;int x=removeQueries[i];active[x]=1;sum[x]=nums[x];
            if(x>0&&active[x-1])join(x,x-1);
            if(x+1<n&&active[x+1])join(x,x+1);
            best=max(best,sum[find(x)]);
        }
        return ans;
    }
};
